export async function loadProfile(userId) {
  const response = await fetch(`/api/users/${userId}`);
  if (!response.ok) {
    throw new Error(`failed to load user ${userId}`);
  }
  const profile = response.json();
  return { name: profile.name, email: profile.email };
}
